import mongoose from 'mongoose';
import { ADMIN_STATUSES, ROLE_VALUES, ROLES } from '@bitbyte/shared';

const { Schema } = mongoose;

const twoFactorSchema = new Schema(
  {
    enabled: { type: Boolean, default: false },
    /** AES-256-GCM encrypted TOTP secret (D-039). Never returned by any API. */
    secretEncrypted: { type: String, default: null },
    /** Secret generated by "enrol start", activated only after a confirmed code. */
    pendingSecretEncrypted: { type: String, default: null },
    pendingCreatedAt: { type: Date, default: null },
    /** Last accepted TOTP time-step; codes at or before it are rejected (replay protection). */
    lastUsedStep: { type: Number, default: null },
    enrolledAt: { type: Date, default: null },
    /** HMAC-SHA-256 hashes of unused recovery codes. */
    recoveryCodeHashes: { type: [String], default: [] },
    recoveryCodesGeneratedAt: { type: Date, default: null },
  },
  { _id: false },
);

/** Administrator account. The only role is super_admin (D-004). Public visitors have no accounts. */
const adminSchema = new Schema(
  {
    name: { type: String, required: true, trim: true, minlength: 1, maxlength: 80 },
    email: {
      type: String,
      required: true,
      trim: true,
      lowercase: true,
      maxlength: 254,
      match: [/^[^\s@]+@[^\s@]+\.[^\s@]+$/, 'Must be a valid e-mail address'],
    },
    passwordHash: { type: String, required: true, select: false },
    role: { type: String, enum: ROLE_VALUES, default: ROLES.SUPER_ADMIN, required: true },
    status: { type: String, enum: ADMIN_STATUSES, default: 'active', required: true },
    failedLoginCount: { type: Number, default: 0, min: 0 },
    lockUntil: { type: Date, default: null },
    lockouts: { type: Number, default: 0, min: 0 },
    lastLoginAt: { type: Date, default: null },
    passwordChangedAt: { type: Date, default: () => new Date() },
    /** Sessions created before this instant are invalid (password/2FA change, disable, revoke-all). */
    sessionsValidAfter: { type: Date, default: () => new Date(0) },
    mustChangePassword: { type: Boolean, default: true },
    twoFactor: { type: twoFactorSchema, default: () => ({}), select: false },
    securityAlertUntil: { type: Date, default: null },
    createdBy: { type: Schema.Types.ObjectId, ref: 'Admin', default: null },
  },
  {
    timestamps: true,
    toJSON: {
      transform(_doc, ret) {
        delete ret.passwordHash;
        delete ret.twoFactor;
        delete ret.__v;
        return ret;
      },
    },
  },
);

adminSchema.index({ email: 1 }, { unique: true });

export const Admin = mongoose.models.Admin ?? mongoose.model('Admin', adminSchema);
